CREATE TYPE public.workspace_role AS ENUM ('owner','admin','branch_manager','sales_manager','agent','marketer','builder_manager','finance','property_owner','investor','customer');
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK(length(display_name)<=100), preferences jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY; CREATE POLICY own_profile ON public.profiles FOR ALL TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('super_admin','operations_admin')), UNIQUE(user_id,role)); GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY; CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_platform_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid()) $$; REVOKE ALL ON FUNCTION public.is_platform_admin() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_platform_admin() TO authenticated;
CREATE TABLE public.tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(name) BETWEEN 2 AND 120),created_by uuid NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')),created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.tenants TO authenticated; GRANT ALL ON public.tenants TO service_role; ALTER TABLE public.tenants ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.branches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),name text NOT NULL,UNIQUE(id,tenant_id)); GRANT SELECT ON public.branches TO authenticated; GRANT ALL ON public.branches TO service_role; ALTER TABLE public.branches ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),user_id uuid NOT NULL,role public.workspace_role NOT NULL DEFAULT 'customer',branch_id uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,user_id),FOREIGN KEY(branch_id,tenant_id) REFERENCES public.branches(id,tenant_id)); GRANT SELECT ON public.memberships TO authenticated; GRANT ALL ON public.memberships TO service_role; ALTER TABLE public.memberships ENABLE ROW LEVEL SECURITY; CREATE INDEX membership_user ON public.memberships(user_id,tenant_id);
CREATE FUNCTION public.tenant_role(t uuid) RETURNS public.workspace_role LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT m.role FROM public.memberships m JOIN public.tenants x ON x.id=m.tenant_id WHERE m.tenant_id=t AND m.user_id=auth.uid() AND x.status='active' $$; REVOKE ALL ON FUNCTION public.tenant_role(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.tenant_role(uuid) TO authenticated;
CREATE FUNCTION public.can_manage(t uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(public.tenant_role(t) IN ('owner','admin'),false) $$; REVOKE ALL ON FUNCTION public.can_manage(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_manage(uuid) TO authenticated;
CREATE FUNCTION public.record_access(t uuid,b uuid,owner_id uuid,crm boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.memberships m JOIN public.tenants x ON x.id=m.tenant_id WHERE m.tenant_id=t AND m.user_id=auth.uid() AND x.status='active' AND (m.role IN ('owner','admin') OR (m.role='branch_manager' AND m.branch_id IS NOT NULL AND m.branch_id=b) OR (crm AND m.role='sales_manager' AND (m.branch_id IS NULL OR m.branch_id=b)) OR (m.role IN ('agent','property_owner','builder_manager','marketer') AND owner_id=auth.uid() AND (m.branch_id IS NULL OR m.branch_id=b)))) $$; REVOKE ALL ON FUNCTION public.record_access(uuid,uuid,uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.record_access(uuid,uuid,uuid,boolean) TO authenticated;
CREATE POLICY tenant_read ON public.tenants FOR SELECT TO authenticated USING(public.tenant_role(id) IS NOT NULL OR public.is_platform_admin()); CREATE POLICY branch_read ON public.branches FOR SELECT TO authenticated USING(public.can_manage(tenant_id)); CREATE POLICY membership_read ON public.memberships FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.can_manage(tenant_id));
CREATE FUNCTION public.create_workspace(business_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF length(trim(business_name)) NOT BETWEEN 2 AND 120 THEN RAISE EXCEPTION 'Business name must be 2 to 120 characters'; END IF; IF (SELECT count(*) FROM public.memberships WHERE user_id=auth.uid() AND role='owner')>=5 THEN RAISE EXCEPTION 'Workspace limit reached'; END IF; INSERT INTO public.tenants(name,created_by) VALUES(trim(business_name),auth.uid()) RETURNING id INTO t; INSERT INTO public.memberships(tenant_id,user_id,role) VALUES(t,auth.uid(),'owner'); RETURN t; END $$; REVOKE ALL ON FUNCTION public.create_workspace(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_workspace(text) TO authenticated;
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(new.id,left(coalesce(new.raw_user_meta_data->>'display_name',''),100)) ON CONFLICT DO NOTHING; RETURN new; END $$; CREATE TRIGGER app_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();